#include <vulkan/vulkan.h>
#include <iostream>
#include <fstream>
#include <vector>
#include <stdexcept>
#include <cstdlib>
int main(int argc,char **argv){VkInstance instance=VK_NULL_HANDLE;try{if(argc!=2)throw std::runtime_error("expected vendor argument");unsigned vendor=std::strtoul(argv[1],nullptr,0);VkApplicationInfo app{VK_STRUCTURE_TYPE_APPLICATION_INFO};app.pApplicationName="instance-only physical precision metadata";app.apiVersion=VK_API_VERSION_1_1;VkInstanceCreateInfo ci{VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};ci.pApplicationInfo=&app;if(vkCreateInstance(&ci,nullptr,&instance)!=VK_SUCCESS)throw std::runtime_error("instance creation failed");uint32_t n=0;if(vkEnumeratePhysicalDevices(instance,&n,nullptr)!=VK_SUCCESS)throw std::runtime_error("physical count failed");std::vector<VkPhysicalDevice> devices(n);if(vkEnumeratePhysicalDevices(instance,&n,devices.data())!=VK_SUCCESS)throw std::runtime_error("physical enumeration failed");unsigned found=0;for(auto p:devices){VkPhysicalDeviceProperties prop{};vkGetPhysicalDeviceProperties(p,&prop);if(prop.vendorID!=vendor)continue;if(prop.deviceType!=VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU&&prop.deviceType!=VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU)throw std::runtime_error("nonhardware physical device");VkPhysicalDeviceFeatures f{};vkGetPhysicalDeviceFeatures(p,&f);++found;std::cout<<"{\"vendor_id\":"<<prop.vendorID<<",\"device_id\":"<<prop.deviceID<<",\"device_type\":"<<prop.deviceType<<",\"api_major\":"<<VK_API_VERSION_MAJOR(prop.apiVersion)<<",\"api_minor\":"<<VK_API_VERSION_MINOR(prop.apiVersion)<<",\"api_patch\":"<<VK_API_VERSION_PATCH(prop.apiVersion)<<",\"shaderFloat64\":"<<(f.shaderFloat64?"true":"false")<<",\"shaderInt64\":"<<(f.shaderInt64?"true":"false")<<",\"shaderInt16\":"<<(f.shaderInt16?"true":"false")<<"}\n";}if(found!=1)throw std::runtime_error("expected exactly one matching hardware GPU");std::ifstream maps("/proc/self/maps");std::cerr<<maps.rdbuf();vkDestroyInstance(instance,nullptr);return 0;}catch(const std::exception&e){if(instance)vkDestroyInstance(instance,nullptr);std::cerr<<e.what()<<'\n';return 1;}}
